/*CM-DATOS-FIN*/

const cmE=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const CM_VARS='--c:#8fb2ff;--zc:#87C9A5;';
const cmCapture=/[?&]t=\d/.test(location.search);                       // con ?t=<ms> no hay reinicios por JavaScript: el instante lo fija la herramienta de capturas
const cmHead=(t,sub)=>`<div class="cm-h"><b>${cmE(t)}</b><span>${cmE(sub)}</span></div>`;
const cmUid=(()=>{let n=0;return ()=>++n})();
const cmBy=(list)=>Object.fromEntries(list.map(p=>[p.n,p]));
const cmPos=h=>`left:${h.x}px;top:${h.y}px;`;
// Etiqueta de una muestra: nombre, filas que cubre y valor abreviado (el exacto está en paridad/CIMIENTOS_GRUPOS.md y en la escena-documento).
const cmLabel=(h,name,u,val,extra='')=>`<div class="cm-l${h.lw>200?' cm-l1':''}" style="left:${h.lx}px;top:${h.ly}px;width:${h.lw}px"><b>${cmE(name)}</b><em>${u} ${u===1?'fila':'filas'}${extra}</em><i>${cmE(val)}</i></div>`;
const cmShort=(s,n)=>s.length>n?s.slice(0,n-1)+'…':s;

/* ---------------------------------------------------------------- SOMBRAS */
const CM_SOM=cmBy(CM.sombras||[]);
const cmSomScene=(sheet,idx,total,kindTitle)=>{
  const names=sheet.n;const isText=sheet.id.indexOf('texto')>=0;
  scene({id:sheet.id,tab:'cimientos',title:`${kindTitle} (${idx} de ${total})`,
    html:()=>{
      const samples=names.map(n=>{const p=CM_SOM[n],h=p.h;
        const body=isText?`<div class="cm-s cm-st" style="${cmPos(h)}"><span style="text-shadow:${p.c}">Aa 128,5</span></div>`:`<div class="cm-s" style="${cmPos(h)}box-shadow:${p.c}"></div>`;
        return body+cmLabel(h,n,p.u,p.ab||p.c,p.m>1?` · ${p.m} valores`:'');
      }).join('');
      return `<div class="cm-sheet" style="${CM_VARS}">${cmHead(kindTitle,`${idx}/${total} · muestras 140 × 84 dp, radio 24`)}${samples}</div>`;
    },
    notes:{tags:[['keep','hoja de calibración']],
      p:[isText?'Cada muestra es un panel gris claro con el texto «Aa 128,5» en blanco y la sombra de texto del preset (las sombras de texto son negras y solo se ven sobre un fondo claro o una foto).':'Cada muestra es un rectángulo de 140 × 84 dp con radio 24 y relleno #1B1B1D sobre el fondo #0B0B0C de la hoja, con la sombra del preset aplicada tal cual. La app dibuja esta misma hoja a 360 × 880 y se comparan las dos capturas.',
         'Si una muestra lleva color de módulo (resplandor «zona» o color dinámico), la hoja fija <b>--c</b> = #8fb2ff y <b>--zc</b> = #87C9A5.'],
      listTitle:'Posición de cada muestra (esquina superior izquierda, dp)',list:names.map(n=>{const p=CM_SOM[n];return `<b>${cmE(n)}</b> · x ${p.h.x}, y ${p.h.y} · ${p.u} filas · alcance ${p.a} dp`})}});
};
{
  const groups={caida:[],anillo:[],interior:[],resplandor:[],nula:[],texto:[]};
  for(const s of (CM.hojas&&CM.hojas.sombras)||[]){const k=s.id.replace(/^cm-som-/,'').replace(/-\d+$/,'');(groups[k]=groups[k]||[]).push(s)}
  for(const s of (CM.hojas&&CM.hojas.texto)||[])groups.texto.push(s);
  const TIT={caida:'Sombras · caídas',anillo:'Sombras · anillos',interior:'Sombras · realces y bordes interiores',resplandor:'Sombras · resplandores',nula:'Sombras · sin sombra',texto:'Sombras de texto'};
  for(const k of ['caida','anillo','interior','resplandor','nula','texto'])groups[k].forEach((s,i)=>cmSomScene(s,i+1,groups[k].length,TIT[k]));
}

/* ---------------------------------------------------------------- VIDRIO Y FILTROS */
const cmPattern=()=>{
  const txt=Array.from({length:44},(_,i)=>'KPKN FIT 0123456789 ABCDEFGHIJ '+(i%2?'SESIÓN ':'RUTINA ')).join('');
  return `<div class="cm-pat"><div class="cm-bars"></div><div class="cm-txt">${txt}</div></div>`;
};
{
  const V=CM.vidrio||[],byH={};V.forEach(p=>{(byH[p.h.hoja]=byH[p.h.hoja]||[]).push(p)});
  const ids=Object.keys(byH);
  ids.forEach((id,i)=>scene({id,tab:'cimientos',title:`Vidrio · backdrop-filter (${i+1} de ${ids.length})`,
    html:()=>`<div class="cm-sheet">${cmPattern()}${cmHead('Vidrio · backdrop-filter',`${i+1}/${ids.length} · franjas de 312 × 72 dp`)}${byH[id].map(p=>`<div class="cm-gl" style="${cmPos(p.h)}width:${p.h.w}px;height:${p.h.h}px;backdrop-filter:${p.c};-webkit-backdrop-filter:${p.c}"></div><div class="cm-gt" style="left:${p.h.lx}px;top:${p.h.ly}px;width:${p.h.lw}px"><b>${cmE(p.n)}</b> · ${p.u} filas · ${cmE(p.c)}</div>`).join('')}</div>`,
    notes:{tags:[['keep','hoja de calibración']],
      p:['Detrás de cada franja hay el mismo fondo: ocho barras de color verticales y líneas de texto de 13 px en blanco, fijos para que el desenfoque se vea y se pueda medir. Cada franja es un rectángulo de 312 × 72 dp, radio 24, solo con el <code>backdrop-filter</code> del preset y un borde interior de 1 dp blanco al 18 %.',
         'En Android &lt; 12 (el flavor base llega a la 24) el desenfoque no existe y cae a un velo: esta hoja es la referencia de Android 12 o superior (el Flip5 lleva Android 16).'],
      listTitle:'Posición de cada franja (dp)',list:byH[id].map(p=>`<b>${cmE(p.n)}</b> · ${cmE(p.c)} · x ${p.h.x}, y ${p.h.y} · ${p.u} filas`)}}));
  const F=CM.filtros||[],byF={};F.forEach(p=>{(byF[p.h.hoja]=byF[p.h.hoja]||[]).push(p)});
  const fids=Object.keys(byF);
  fids.forEach((id,i)=>scene({id,tab:'cimientos',title:`Filtros · filter (${i+1} de ${fids.length})`,
    html:()=>`<div class="cm-sheet">${cmHead('Filtros · filter',`${i+1}/${fids.length} · muestras de 140 × 84 dp`)}${byF[id].map(p=>`<div class="cm-fs" style="${cmPos(p.h)}"><div class="cm-fsi" style="filter:${p.c}">${cmPattern()}</div></div>${cmLabel(p.h,p.n,p.u,p.c)}`).join('')}</div>`,
    notes:{tags:[['keep','hoja de calibración']],
      p:['Cada muestra es el mismo fondo de barras y texto recortado a 140 × 84 dp (radio 24) con el <code>filter</code> del preset sobre el propio elemento. Sirve para el desenfoque de halos, el apagado de fotos y vídeo y los ajustes de brillo y saturación.'],
      listTitle:'Posición de cada muestra (dp)',list:byF[id].map(p=>`<b>${cmE(p.n)}</b> · ${cmE(p.c)} · x ${p.h.x}, y ${p.h.y} · ${p.u} filas`)}}));
}

/* ---------------------------------------------------------------- DEGRADADOS Y RESPLANDORES */
{
  const G=CM.degradados||[],byG={};G.forEach(p=>{(byG[p.h.hoja]=byG[p.h.hoja]||[]).push(p)});
  const ids=Object.keys(byG);
  const extra=n=>n==='rejilla'?'background-size:24px 24px;':'';
  ids.forEach((id,i)=>scene({id,tab:'cimientos',title:`Degradados y resplandores (${i+1} de ${ids.length})`,
    html:()=>`<div class="cm-sheet" style="${CM_VARS}">${cmHead('Degradados y resplandores',`${i+1}/${ids.length} · muestras 140 × 84 dp, radio 24`)}${byG[id].map(p=>`<div class="cm-gs" style="${cmPos(p.h)}background-image:${p.c};${extra(p.n)}"></div>${cmLabel(p.h,p.n,p.u,cmShort(p.c,92))}`).join('')}</div>`,
    notes:{tags:[['keep','hoja de calibración']],
      p:['Cada muestra pinta el degradado canónico del preset como <code>background-image</code> de un rectángulo de 140 × 84 dp (radio 24) sobre el fondo #0B0B0C. Los velos (de transparente a un color) se funden con ese fondo; los resplandores son radiales de borde transparente. La rejilla lleva <code>background-size: 24px 24px</code>.',
         'Los degradados con color dinámico usan <b>--c</b> = #8fb2ff y <b>--zc</b> = #87C9A5.'],
      listTitle:'Posición de cada muestra (dp)',list:byG[id].map(p=>`<b>${cmE(p.n)}</b> · x ${p.h.x}, y ${p.h.y} · ${p.u} filas`)}}));
}

/* ---------------------------------------------------------------- MOVIMIENTO: curvas y duraciones (círculo de 40 dp que recorre 200 dp) */
const CM_HOLD=600,CM_TRAVEL=200,CM_ROWS=12,CM_ROW_H=64,CM_ROW_Y0=64;
const cmCycle=ms=>2*ms+2*CM_HOLD;
const cmRideCss=(id,ms,curve)=>{
  const c=cmCycle(ms),p=x=>Math.round(x/c*100000)/1000;
  return `@keyframes cm-ride-${id}{0%{transform:translateX(0);animation-timing-function:${curve}}${p(ms)}%{transform:translateX(${CM_TRAVEL}px);animation-timing-function:linear}${p(ms+CM_HOLD)}%{transform:translateX(${CM_TRAVEL}px);animation-timing-function:${curve}}${p(2*ms+CM_HOLD)}%{transform:translateX(0)}100%{transform:translateX(0)}}.cm-ride-${id}{animation:cm-ride-${id} ${c}ms linear infinite}`;
};
const cmRows=(rows)=>{
  const css=[],html=rows.map((r,i)=>{
    const id=cmUid();css.push(cmRideCss(id,r.ms,r.curve));
    const y=CM_ROW_Y0+i*CM_ROW_H;
    return `<div class="cm-row" style="top:${y}px"><div class="cm-rl"><b>${cmE(r.name)}</b> · ${cmE(r.sub)} · <b>${r.ms} ms</b></div><div class="cm-trk"><div class="cm-ghost"></div><div class="cm-ball cm-ride-${id}"></div></div></div>`;
  }).join('');
  return `<style data-pkg="cm">${css.join('')}</style>${html}`;
};
{
  const rows=[];
  for(const c of CM.curvas||[]){
    const d=(c.dt&&c.dt.length?c.dt:[{ms:280}]);
    d.forEach(x=>rows.push({name:c.n,sub:cmShort(c.c,36),ms:x.ms,curve:c.c,desc:c.desc,usos:x.usos}));
  }
  const nS=Math.max(1,Math.ceil(rows.length/CM_ROWS));
  for(let s=0;s<nS;s++){
    const chunk=rows.slice(s*CM_ROWS,(s+1)*CM_ROWS);
    scene({id:`cm-mov-curvas-${s+1}`,tab:'cimientos',title:`Curvas × duración (${s+1} de ${nS})`,
      html:()=>`<div class="cm-sheet">${cmHead('Curvas de movimiento',`${s+1}/${nS} · círculo de 40 dp que recorre 200 dp`)}${cmRows(chunk)}</div>`,
      notes:{tags:[['keep','hoja de calibración']],
        p:[`Cada fila es un par curva-duración (los dos más usados de cada curva). El círculo (40 dp, #F2EEE6) va de x 60 a x 260 en la duración y la curva indicadas, espera ${CM_HOLD} ms, vuelve con la misma curva y espera otros ${CM_HOLD} ms. El ciclo completo dura 2 × duración + ${2*CM_HOLD} ms; el instante 0 es el principio de la ida.`,
           'Para comparar con la app: capturas a 0, 25, 50 y 100 % de la duración de la ida (<code>node tools/shots.cjs shot cm-mov-curvas-1 --t=&lt;ms&gt;</code>). Las curvas con rebasado (resorte) pasan de x 260 y vuelven.'],
        listTitle:'Filas (y de la fila, dp; la pista empieza en x 60)',list:chunk.map((r,i)=>`<b>${cmE(r.name)}</b> · ${r.ms} ms · y ${CM_ROW_Y0+i*CM_ROW_H} · ${cmE(r.curve)}${r.desc?' — '+cmE(r.desc):''}`)}});
  }
  const std=(CM.curvas||[]).find(c=>c.n==='estandar')||{c:'cubic-bezier(0.2, 0.8, 0.2, 1)'};
  const drows=(CM.duraciones||[]).map(d=>({name:'estandar',sub:d.ex?'duración exacta':'escalón de la escala',ms:d.ms,curve:std.c}));
  const nD=Math.max(1,Math.ceil(drows.length/CM_ROWS));
  for(let s=0;s<nD;s++){
    const chunk=drows.slice(s*CM_ROWS,(s+1)*CM_ROWS);
    scene({id:`cm-mov-duraciones-${s+1}`,tab:'cimientos',title:`Escala de duraciones (${s+1} de ${nD})`,
      html:()=>`<div class="cm-sheet">${cmHead('Escala de duraciones',`${s+1}/${nD} · curva «estandar», círculo de 40 dp, 200 dp`)}${cmRows(chunk)}</div>`,
      notes:{tags:[['keep','hoja de calibración']],
        p:['Todas las duraciones de la escala con la misma curva «estandar», para ver (y medir) cuánto dura cada una. Mismo recorrido y mismas esperas que la hoja de curvas.'],
        listTitle:'Duraciones (ms · filas del inventario que cubre · mayor ajuste)',list:chunk.map((r,i)=>{const d=(CM.duraciones||[]).find(x=>x.ms===r.ms)||{};return `<b>${r.ms} ms</b> · ${d.u||0} filas · ${d.m||0} valores · ajuste ${d.dm||'—'} · y ${CM_ROW_Y0+i*CM_ROW_H}`})}});
  }
}

/* ---------------------------------------------------------------- MOVIMIENTO: familias de @keyframes (con los @keyframes REALES del lienzo) */
const CM_DEMO_Y0=64,CM_CELL_W=152,CM_CELL_H=128,CM_CELL_X=[16,192];
const cmDemoCss=d=>`${d.nombre} ${d.dur} ${d.fn} ${d.delay} ${d.count} ${d.dir} ${d.fill}`;
const cmDemoEl=(f)=>{
  const d=f.demo,an=cmDemoCss(d),once=d.count!=='infinite';
  const base=`--cm-an:${cmE(an)}`;
  const cls='cm-d'+(once?' cm-once':'');
  switch(f.f){
    case 'dibujo-trazo':return `<svg class="cm-dsv" viewBox="0 0 100 40" width="100" height="40"><path class="${cls}" style="${base}" d="M6 30 C 26 -6, 52 46, 94 8" fill="none" stroke="#F2EEE6" stroke-width="3.5" stroke-linecap="round" pathLength="100" stroke-dasharray="100" stroke-dashoffset="100"/></svg>`;
    case 'giro':return `<div class="${cls} cm-spin" style="${base}"></div>`;
    case 'brillo-barrido':return `<div class="${cls} cm-sk" style="${base}"></div>`;
    case 'crece-x':return `<div class="cm-bar"><div class="${cls}" style="${base};transform-origin:0 50%;height:100%;background:#F2EEE6;border-radius:5px"></div></div>`;
    case 'crece-y':return `<div class="cm-bary"><div class="${cls}" style="${base};transform-origin:50% 100%;width:100%;height:100%;background:#F2EEE6;border-radius:5px"></div></div>`;
    case 'barrido-ancho':return `<div class="cm-bar"><div class="${cls}" style="${base};height:100%;width:0;background:#F2EEE6;border-radius:5px"></div></div>`;
    case 'barrido-linea':return `<div class="cm-box"><div class="${cls}" style="${base};--vfh:48px;position:absolute;left:0;right:0;top:0;height:3px;background:#F2EEE6;border-radius:2px"></div></div>`;
    case 'hoja-sube':case 'hoja-baja':return `<div class="cm-box"><div class="${cls}" style="${base};position:absolute;left:0;right:0;bottom:0;height:34px;background:#1B1B1D;border-radius:14px 14px 0 0;box-shadow:inset 0 1px 0 #ffffff1c"></div></div>`;
    case 'revelado':return `<div class="${cls} cm-vid" style="${base};--vx:0px;--vy:0px;--vs:1"></div>`;
    case 'entrada-implicita':return `<div class="${cls} cm-chip" style="${base};opacity:0;transform:translateY(12px)">Chip</div>`;
    case 'caida':return `<div class="cm-box"><div class="${cls}" style="${base};width:18px;height:18px;border-radius:4px;background:#F49A6E;margin:6px auto 0"></div></div>`;
    case 'onda':case 'onda-anillo':case 'pulso-anillo':case 'ignicion':return `<div class="${cls} cm-dot" style="${base};--zc:#87C9A5"></div>`;
    case 'destello':return `<div class="${cls} cm-chip" style="${base}">Destello</div>`;
    case 'despliegue-fila':return `<div class="cm-box"><div class="${cls} cm-chip" style="${base};--module:#111111;background:#111111;width:100%">Serie 3</div></div>`;
    case 'aviso':return `<div class="${cls} cm-chip" style="${base}">+2,5 kg</div>`;
    case 'latido':case 'pulso':case 'flotar':case 'asentar':case 'rebote':case 'rebote-aparece':case 'aparece-escala':return `<div class="${cls} cm-dot" style="${base}"></div>`;
    default:return `<div class="${cls} cm-chip" style="${base}">Muestra</div>`;
  }
};
const cmReplay=(phone)=>{
  if(cmCapture||!phone)return;
  const run=()=>{if(!phone.isConnected){clearInterval(phone.__cmTimer);return}
    phone.querySelectorAll('.cm-once').forEach(el=>{el.style.animation='none';void el.offsetWidth;el.style.animation=''})};
  clearInterval(phone.__cmTimer);phone.__cmTimer=setInterval(run,3200);
};
{
  const K=CM.keyframes||[];
  const ESC=[['entradas','Entradas, fundidos y hojas',['entradas','hojas']],['pulsaciones','Pulsaciones y rebotes',['pulsaciones']],['bucles','Pulsos y bucles infinitos',['bucles']],['trazos','Trazos, barras y destellos',['trazos']]];
  for(const [id,title,esc] of ESC){
    const fams=K.filter(f=>esc.includes(f.esc));if(!fams.length)continue;
    const per=12,n=Math.ceil(fams.length/per);
    for(let s=0;s<n;s++){
      const chunk=fams.slice(s*per,(s+1)*per);
      scene({id:`cm-mov-${id}${n>1?'-'+(s+1):''}`,tab:'cimientos',title:`${title}${n>1?` (${s+1} de ${n})`:''}`,
        html:()=>`<div class="cm-sheet">${cmHead(title,`${n>1?`${s+1}/${n} · `:''}@keyframes reales del lienzo, uno por familia`)}${chunk.map((f,i)=>{
          const x=CM_CELL_X[i%2],y=CM_DEMO_Y0+Math.floor(i/2)*CM_CELL_H;
          const d=f.demo;
          return `<div class="cm-cell" style="left:${x}px;top:${y}px;width:${CM_CELL_W}px;height:${CM_CELL_H-8}px"><div class="cm-cl"><b>${cmE(f.f)}</b><span>${cmE(d.nombre)} · ${cmE(d.dur)} · ${cmE((CM.curvas||[]).filter(c=>c.c===d.fn).map(c=>c.n)[0]||cmShort(d.fn,26))}${d.count==='infinite'?' · ∞':''}</span></div><div class="cm-stage">${cmDemoEl(f)}</div></div>`;
        }).join('')}</div>`,
        after:(phone)=>cmReplay(phone),
        notes:{tags:[['keep','hoja de calibración']],
          p:['Una celda por familia estructural de <code>@keyframes</code>. Cada una anima el <b>@keyframes real</b> más usado de la familia, con su duración, curva, retardo, repetición y relleno más usados (están en la celda). Las entradas se repiten cada 3,2 s al verlas en el lienzo; los bucles son continuos. En la captura con <code>--t=&lt;ms&gt;</code> el reloj queda congelado en ese instante desde el principio de la animación.',
             'Celdas de 152 × 120 dp: columnas en x 16 y 192; filas cada 128 dp desde y 64. El elemento animado está centrado en el escenario de la celda (60 dp de alto).'],
          listTitle:'Familias (@keyframes que agrupa)',list:chunk.map(f=>`<b>${cmE(f.f)}</b> — ${cmE(f.desc)}. Agrupa: ${f.n.map(cmE).join(', ')}`)}});
    }
  }
}

/* ---------------------------------------------------------------- MOVIMIENTO: cuenta de cifras (animateIn: data-count) */
scene({id:'cm-mov-cuenta',tab:'cimientos',title:'Cuenta de cifras',
  html:()=>`<div class="cm-sheet">${cmHead('Cuenta de cifras','salida cúbica 1 − (1 − t)³ en 1100 ms')}
    ${[['Series',1247,0,'',70],['Calorías',2150,0,' kcal',190],['Peso',82.5,1,' kg',310],['Volumen',18420,0,' kg',430],['Proteína',164.8,1,' g',550]].map(r=>`<div class="cm-num" style="top:${r[4]}px"><i>${r[0]}</i><b><span data-count="${r[1]}" data-dec="${r[2]}">0</span>${r[3]}</b></div>`).join('')}
    <div class="cm-hint" style="top:690px">Mismo contador que usan Inicio y los resúmenes del lienzo: <code>[data-count]</code>, 1100 ms, sin retardo, cifras con tabulares y coma decimal. Arranca al abrir la hoja.</div></div>`,
  after:(phone)=>{animateIn(phone)},
  notes:{tags:[['keep','hoja de calibración']],
    p:['Los contadores del lienzo (<code>animateIn</code> con <code>[data-count]</code>) cuentan de 0 al valor con la salida cúbica <b>1 − (1 − t)³</b> durante <b>1100 ms</b> y formatean con coma decimal y punto de millar. En la app el mismo contador debe llegar al valor final en 1100 ms con esa curva (Compose: <code>tween(1100, easing = CubicBezierEasing(0.33f, 1f, 0.68f, 1f))</code> es la aproximación estándar de la salida cúbica).',
       'Para capturarla en un instante: <code>node tools/shots.cjs shot cm-mov-cuenta --t=275</code> (25 %), <code>--t=550</code>, <code>--t=1100</code>.'],
    listTitle:'Filas (y en dp; las cifras van en x 24)',list:['Series · 1.247 · y 70','Calorías · 2.150 kcal · y 190','Peso · 82,5 kg · y 310','Volumen · 18.420 kg · y 430','Proteína · 164,8 g · y 550']}});

/* ---------------------------------------------------------------- DOCUMENTOS */
const cmDocTable=(head,rows)=>`<div class="dtable-wrap"><table class="dtable"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const cmCode=s=>`<code class="cm-code">${cmE(s)}</code>`;
{
  const R=CM.resumen||{};
  const row=(k,v)=>[k,String((v||{}).valores||0),`<b>${(v||{}).presets||0}</b>`];
  scene({id:'cm-doc-resumen',tab:'cimientos',title:'Cómo leer los cimientos',doc:()=>`<div class="cm-doc">
    <h2>Cimientos: de 101 sombras y 110 animaciones a un catálogo finito</h2>
    <p>El lienzo aprobado usa muchos valores casi iguales. Los <b>cimientos</b> de la app (<code>ui/design/depth</code> y <code>ui/design/motion</code>) los agrupan en <b>presets</b>: cada uno tiene UN valor canónico exacto (el del miembro más usado, sin promediar) y todas las pantallas lo usan por su nombre. Las hojas de esta pestaña son las <b>hojas de calibración</b>: la app dibuja las mismas a 360 × 880 y se compara con estas capturas hasta que sean iguales.</p>
    ${cmDocTable(['Familia','Valores distintos','Presets'],[row('Sombras (box-shadow)',R.sombras),row('Sombras de texto',R.textos),row('Vidrio (backdrop-filter)',R.vidrio),row('Filtros (filter)',R.filtros),row('Curvas',R.curvas),row('Duraciones',R.duraciones),row('Retardos',R.retardos),row('Degradados',R.degradados),row('@keyframes (por familia)',R.keyframes)])}
    <h3>Tolerancias de la agrupación</h3>
    <ul>${Object.entries(CM.tolerancias||{}).map(([k,v])=>`<li><b>${cmE(k)}</b>: ${cmE(v)}</li>`).join('')}</ul>
    <h3>Geometría de las hojas</h3>
    <ul>
      <li>Todas las hojas son de <b>360 × 880 dp</b>, sin marco, sin barra de estado ni barra de inicio, con el origen en la esquina superior izquierda; el fondo es <b>#0B0B0C</b> y la superficie de las muestras <b>#1B1B1D</b>.</li>
      <li><b>Sombras</b>: muestras de <b>140 × 84 dp, radio 24</b>. Alcance ≤ 14 dp: rejilla de 2 columnas (x 24 y x 196) y 5 filas (y 72 + 150 · fila), etiqueta debajo. Alcance mayor: una columna (x 110), la etiqueta encima y la y de cada fila según lo que sobresale la sombra (las posiciones exactas de cada muestra están en la nota de cada escena y en <code>paridad/CIMIENTOS_GRUPOS.md</code>).</li>
      <li><b>Vidrio</b>: franjas de <b>312 × 72 dp</b> (x 24, y 72 + 108 · fila, 7 por hoja) sobre barras de color y texto fijos. <b>Filtros</b> y <b>degradados</b>: muestras de 140 × 84 dp en rejilla de 2 × 5 (x 24 y 196; y 72 + 150 · fila).</li>
      <li><b>Movimiento</b>: círculo de <b>40 dp</b> que recorre <b>200 dp</b> (x 60 → 260), filas cada 64 dp desde y 64; espera de 600 ms en cada extremo; el instante 0 es el principio de la ida. Familias de <code>@keyframes</code>: celdas de 152 × 120 dp (x 16 y 192; y 64 + 128 · fila).</li>
    </ul>
    <h3>Cómo se captura</h3>
    <ul><li><code>node tools/shots.cjs shot cm-som-caida-1</code> · <code>--t=&lt;ms&gt;</code> congela las animaciones CSS y el movimiento de JavaScript en ese instante.</li><li>Las hojas de sombras, vidrio y degradados son estáticas: una sola captura. Las de movimiento se comparan en 0, 25, 50 y 100 % de la duración.</li></ul></div>`});
  const S=(CM.grupos&&CM.grupos.sombras)||[];
  scene({id:'cm-doc-sombras',tab:'cimientos',title:'Tabla de agrupación · sombras',doc:()=>`<div class="cm-doc">
    <h2>Sombras: ${S.length} presets</h2>
    <p>Valor canónico exacto (el del miembro más usado), filas del inventario que cubre, valores que agrupa y la mayor distancia de un miembro al canónico (x, y, desenfoque y extensión en dp; alfa en unidades; canal de color en 0-255).</p>
    ${cmDocTable(['Preset','Tipo','Valor canónico','Filas','Agrupa','Mayor distancia'],S.map(p=>[`<b>${cmE(p.n)}</b>`,cmE(p.k),cmCode(p.c),p.u,p.mm.length>1?p.mm.map(m=>cmCode(m[0])+' ('+m[1]+')').join('<br>'):'(solo él)',cmE(p.dm)]))}</div>`});
  const rest=[];
  rest.push('<h2>Vidrio, filtros, curvas, duraciones y degradados</h2><p>Los valores canónicos exactos. La tabla completa, con todos los miembros de cada grupo y la tolerancia aplicada, está en <code>paridad/CIMIENTOS_GRUPOS.md</code>.</p>');
  rest.push('<h3>Vidrio (backdrop-filter)</h3>'+cmDocTable(['Preset','Valor canónico','Filas','Valores','Mayor distancia'],(CM.vidrio||[]).map(p=>[`<b>${cmE(p.n)}</b>`,cmCode(p.c),p.u,p.m,cmE(p.dm)])));
  rest.push('<h3>Filtros (filter)</h3>'+cmDocTable(['Preset','Valor canónico','Filas','Valores','Mayor distancia'],(CM.filtros||[]).map(p=>[`<b>${cmE(p.n)}</b>`,cmCode(p.c),p.u,p.m,cmE(p.dm)])));
  rest.push('<h3>Curvas</h3>'+cmDocTable(['Preset','Valor canónico','Filas','Para qué','Pares más usados','Mayor distancia'],(CM.curvas||[]).map(p=>[`<b>${cmE(p.n)}</b>`,cmCode(p.c),p.u,cmE(p.desc||''),(p.dt||[]).map(d=>d.ms+' ms').join(', ')||'—',cmE(p.dm)])));
  rest.push('<h3>Duraciones (ms)</h3>'+cmDocTable(['Preset','Ms','Exacta','Filas','Valores','Mayor ajuste'],(CM.duraciones||[]).map(p=>[`<b>${cmE(p.n)}</b>`,p.ms,p.ex?'sí':'escala',p.u,p.m,cmE(p.dm)])));
  rest.push('<h3>Degradados</h3>'+cmDocTable(['Preset','Tipo','Valor canónico','Filas','Valores','Mayor distancia'],(CM.degradados||[]).map(p=>[`<b>${cmE(p.n)}</b>`,cmE(p.t),cmCode(cmShort(p.c,150)),p.u,p.m,cmE(p.dm)])));
  rest.push('<h3>Familias de @keyframes</h3>'+cmDocTable(['Familia','Qué hace','Filas','Agrupa','Duraciones','Curvas','Repite'],(CM.keyframes||[]).map(f=>[`<b>${cmE(f.f)}</b>`,cmE(f.desc),f.u,f.n.map(cmE).join(', '),cmE((f.res.duraciones||[]).slice(0,4).join(', ')),cmE((f.res.curvas||[]).slice(0,3).join(', ')),cmE((f.res.repeticiones||[]).join(', '))])));
  scene({id:'cm-doc-resto',tab:'cimientos',title:'Tabla de agrupación · el resto',doc:()=>'<div class="cm-doc">'+rest.join('')+'</div>'});
}
